export function TaskTypeIcon({
  type,
  size = 24,
  className,
}: {
  type: TaskCardType;
  size?: number;
  className?: string;
}) {
  const common = {
    width: size,
    height: size,
    viewBox: '0 0 24 24',
    fill: 'none',
    className: cn('shrink-0', className),
    'aria-hidden': true,
    focusable: false,
  } as const;

  if (type === 'riddle') {
    // Рисунком, а не текстом: текстовый знак вопроса зависит от
    // шрифта и в Unbounded заметно уезжает вверх от центра.
    return (
      <svg {...common}>
        <path
          d="M8.3 8.5a3.7 3.7 0 1 1 5.2 3.4c-1.1.5-1.7 1.3-1.7 2.4v.6"
          stroke="currentColor"
          strokeWidth="2.6"
          strokeLinecap="round"
        />
        <circle cx="12" cy="18.6" r="1.65" fill="currentColor" />
      </svg>
    );
  }

  if (type === 'photo') {
    return (
      <svg {...common}>
        <path d={CAMERA_PATH} fill="currentColor" fillRule="evenodd" clipRule="evenodd" />
      </svg>
    );
  }

  // active — двое бегущих: задание делают, а не снимают.
  return (
    <svg {...common}>
      <path d={RUNNERS_PATH} fill="currentColor" fillRule="evenodd" clipRule="evenodd" />
    </svg>
  );
}

/**
 * Мелкий значок рядом со строкой о месте: крест, район или ничего.
 *
 * Крест — тот же, что и на карте. Повторение намеренное: человек
 * читает «точка на карте», видит крест и потом находит его же
 * среди тайлов, не гадая, что из значков относится к его заданию.
 */
export function PlaceMark({ type, className }: { type: TaskCardType; className?: string }) {
  const common = {
    width: 13,
    height: 13,
    viewBox: '0 0 14 14',
    fill: 'none',
    className: cn('shrink-0', className),
    'aria-hidden': true,
    focusable: false,
  } as const;

  if (type === 'photo') {
    return (
      <svg {...common}>
        <path
          d="M2.5 2.5 11.5 11.5M11.5 2.5 2.5 11.5"
          stroke="currentColor"
          strokeWidth="2.2"
          strokeLinecap="round"
        />
      </svg>
    );
  }

  if (type === 'riddle') {
    return (
      <svg {...common}>
        <circle
          cx="7"
          cy="7"
          r="5"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeDasharray="2.4 2.6"
        />
      </svg>
    );
  }

  // Актив к месту не привязан — рисовать нечего, но пустое место
  // в ряду сохраняем, чтобы строки не прыгали по вертикали.
  return (
    <svg {...common}>
      <path d="M2.5 7h9" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  );
}
